using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;
static class UpdateAssist {
 [STAThread]static int Main(string[] args){string app=null;bool quiet=false;for(int i=0;i<args.Length;i++){if(args[i]=="--app"&&i+1<args.Length)app=Path.GetFullPath(args[++i]);else if(args[i]=="--quiet")quiet=true;}if(app==null)return 2;var processes=UpdateProtocol.Running(app);if(processes.Length==0)return 0;if(quiet)return processes.All(UpdateProtocol.RequestClose)?0:1;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var f=new CloseForUpdate(app)){f.ShowDialog();return f.Done?0:1;}}
}
